import (
	"fmt"
	"strings"
)

func main() {
	var n int
	var s string
	fmt.Scan(&n)
	fmt.Scan(&s)

	// Generate all rotations of s
	rotations := make(map[string]bool)
	for i := 0; i < len(s); i++ {
		rot := s[i:] + s[:i]
		rotations[rot] = true
	}

	// Check if any rotation of s is a substring of any rotation of t
	count := 0
	for mask := 0; mask < (1 << n); mask++ {
		t := ""
		for i := 0; i < n; i++ {
			if (mask>>i)&1 == 1 {
				t += "1"
			} else {
				t += "0"
			}
		}

		// Check all rotations of t
		found := false
		for i := 0; i < n; i++ {
			rotT := t[i:] + t[:i]
			for rotS := range rotations {
				if strings.Contains(rotT, rotS) {
					found = true
					break
				}
			}
			if found {
				break
			}
		}

		if found {
			count++
		}
	}

	fmt.Println(count)
}
