	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int
	fmt.Fscan(in, &n)
	var s string
	fmt.Fscan(in, &s)
	m := len(s)
	if m > n {
		fmt.Println(0)
		return
	}
	// Build failure function for KMP
	fail := make([]int, m)
	for i := 1; i < m; i++ {
		j := fail[i-1]
		for j > 0 && s[i] != s[j] {
			j = fail[j-1]
		}
		if s[i] == s[j] {
			j++
		}
		fail[i] = j
	}
	// dp[pos][state] = number of ways
	// state is the current position in the pattern (0..m)
	// We use a 2D array for DP
	dp := make([][]int, n+1)
	for i := range dp {
		dp[i] = make([]int, m+1)
	}
	dp[0][0] = 1
	for i := 0; i < n; i++ {
		for state := 0; state <= m; state++ {
			if dp[i][state] == 0 {
				continue
			}
			for c := 0; c < 2; c++ {
				ch := byte('0' + c)
				ns := state
				for ns > 0 && ch != s[ns] {
					ns = fail[ns-1]
				}
				if ch == s[ns] {
					ns++
				}
				if ns < m {
					dp[i+1][ns] += dp[i][state]
				}
			}
		}
	}
	// Sum all states that have reached m (found the substring)
	total := 0
	for state := 0; state <= m; state++ {
		total += dp[n][state]
	}
	fmt.Println(total)
}
