	n := toInt(reader.readLine())
	s := reader.readLine()
	m := len(s)
	if m == 0 {
		fmt.Println(1 << n)
		return
	}
	// Build failure function for KMP
	fail := make([]int, m)
	for i := 1; i < m; i++ {
		j := fail[i-1]
		for j > 0 && s[i] != s[j] {
			j = fail[j-1]
		}
		if s[i] == s[j] {
			j++
		}
		fail[i] = j
	}
	// dp[i][j] = number of strings of length i, ending in state j (matched j chars of s)
	// We need to count all strings of length n that reach state m at least once
	// Use inclusion-exclusion: total = 2^n - (strings that never reach state m)
	// dp[i][j] for j < m
	dp := make([][]int, n+1)
	for i := range dp {
		dp[i] = make([]int, m)
	}
	dp[0][0] = 1
	for i := 0; i < n; i++ {
		for j := 0; j < m; j++ {
			if dp[i][j] == 0 {
				continue
			}
			for _, c := range []byte{'0', '1'} {
				jj := j
				for jj > 0 && c != s[jj] {
					jj = fail[jj-1]
				}
				if c == s[jj] {
					jj++
				}
				if jj < m {
					dp[i+1][jj] += dp[i][j]
				}
			}
		}
	}
	// Sum all dp[n][j] for j < m: these are strings that never matched s
	avoid := 0
	for j := 0; j < m; j++ {
		avoid += dp[n][j]
	}
	total := 1 << n
	fmt.Println(total - avoid)
}

type bufReader struct {
	reader *bufio.Reader
}

func bufReader() *bufReader {
	return &bufReader{bufio.NewReader(os.Stdin)}
}

func (r *bufReader) readLine() string {
	line, _ := r.reader.ReadString('\n')
	for i := len(line) - 1; i >= 0; i-- {
		if line[i] == '\n' || line[i] == '\r' {
			line = line[:i]
		} else {
			break
		}
	}
	return line
}

func toInt(s string) int {
	n := 0
	for _, c := range s {
		n = n*10 + int(c-'0')
	}
	return n
}
