package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	reader := bufio.NewReader(os.Stdin)
	var n int
	fmt.Fscan(reader, &n)
	var s string
	fmt.Fscan(reader, &s)
	m := len(s)
	if m > n {
		fmt.Println(0)
		return
	}

	// Build failure function for KMP
	fail := make([]int, m)
	for i := 1; i < m; i++ {
		j := fail[i-1]
		for j > 0 && s[i] != s[j] {
			j = fail[j-1]
		}
		if s[i] == s[j] {
			j++
		}
		fail[i] = j
	}

	// Build transition table for KMP automaton
	trans := make([][2]int, m+1)
	for state := 0; state <= m; state++ {
		for c := 0; c < 2; c++ {
			if state < m && s[state] == byte('0'+c) {
				trans[state][c] = state + 1
			} else {
				if state == 0 {
					trans[state][c] = 0
				} else {
					trans[state][c] = trans[fail[state-1]][c]
				}
			}
		}
	}

	// DP[i][state] = number of ways after i steps with current state
	dp := make([][]int, n+1)
	for i := range dp {
		dp[i] = make([]int, m+1)
	}
	dp[0][0] = 1

	for i := 0; i < n; i++ {
		for state := 0; state <= m; state++ {
			if dp[i][state] == 0 {
				continue
			}
			for c := 0; c < 2; c++ {
				nextState := trans[state][c]
				if nextState == m {
					// Once we reach the full match state, we stay there
					dp[i+1][m] += dp[i][state]
				} else {
					dp[i+1][nextState] += dp[i][state]
				}
			}
		}
	}

	// The answer is the number of strings that reached the full match state at any point
	fmt.Println(dp[n][m])
}
