package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	reader := bufio.NewReader(os.Stdin)
	var n int
	fmt.Fscan(reader, &n)
	var s string
	fmt.Fscan(reader, &s)
	m := len(s)

	// Compute failure function for KMP
	failure := make([]int, m)
	for i := 1; i < m; i++ {
		j := failure[i-1]
		for j > 0 && s[i] != s[j] {
			j = failure[j-1]
		}
		if s[i] == s[j] {
			j++
		}
		failure[i] = j
	}

	// DP[i][j] is the number of strings of length i with current KMP state j
	// that do not contain s as a substring
	dp := make([][]int, n+1)
	for i := range dp {
		dp[i] = make([]int, m)
	}
	dp[0][0] = 1

	for i := 0; i < n; i++ {
		for j := 0; j < m; j++ {
			if dp[i][j] == 0 {
				continue
			}
			for c := '0'; c <= '1'; c++ {
				nextJ := j
				for nextJ > 0 && byte(c) != s[nextJ] {
					nextJ = failure[nextJ-1]
				}
				if byte(c) == s[nextJ] {
					nextJ++
				}
				if nextJ < m {
					dp[i+1][nextJ] += dp[i][j]
				}
			}
		}
	}

	total := 1 << n
	notContain := 0
	for j := 0; j < m; j++ {
		notContain += dp[n][j]
	}
	fmt.Println(total - notContain)
}
